assets={'S08':'assets/keyframes/S08.png','S08_end':'assets/keyframes/S06b.png'};story={'shots':[{'id':'S08','asset':'S08','start_frame':0,'end_frame':150}]};states={'S08':[{'offset_frame':0,'asset':'S08'},{'offset_frame':149,'asset':'S08_end'}]}
